changeSet.sql:
INSERT INTO role_authorities (role_id, authority_id)
SELECT (SELECT id FROM role WHERE name = 'ROLE_CUSTOMER'),
       (SELECT id FROM authority WHERE code = 'parcel:read');

-- Parcel 1: Colombo to Galle, In Transit INSERT INTO parcel (tracking_id, origin_station_id, destination_station_id, sender_user_id, processed_by_user_id, receiver_name, receiver_phone, total_weight_in_kg, total_price, description, status, created_at) VALUES ('SLR-20251009-001', (SELECT id FROM station WHERE code = 'FOT'), (SELECT id FROM station WHERE code = 'GLE'), (SELECT id FROM app_user WHERE mobile_number = '0770000001'), (SELECT user_id FROM employee_profile WHERE employee_id = 'SLR-CLK-002'), 'Kavitha Silva', '0765554321', 3.0, -- Total weight: 2.5 + 0.5 600.00, -- Total price: 450 + 150 'Electronics and Documents', 'IN_TRANSIT', CURRENT_TIMESTAMP);
-- Items for Parcel 1 INSERT INTO parcel_item (parcel_id, type, category, weight_in_kg, quantity, fee, created_at) VALUES ((SELECT id FROM parcel WHERE tracking_id = 'SLR-20251009-001'), 'Laptop', 'ELECTRONICS', 2.5, 1, 450.00, CURRENT_TIMESTAMP), ((SELECT id FROM parcel WHERE tracking_id = 'SLR-20251009-001'), 'Book', 'OTHER', 0.5, 1, 150.00, CURRENT_TIMESTAMP);
-- Parcel 2: Kandy to Jaffna, Delivered INSERT INTO parcel (tracking_id, origin_station_id, destination_station_id, sender_user_id, processed_by_user_id, receiver_name, receiver_phone, total_weight_in_kg, total_price, description, status, created_at) VALUES ('SLR-20251009-002', (SELECT id FROM station WHERE code = 'KAD'), (SELECT id FROM station WHERE code = 'JAF'), (SELECT id FROM app_user WHERE mobile_number = '0710000002'), (SELECT user_id FROM employee_profile WHERE employee_id = 'SLR-CLK-002'), 'Arun Kumar', '0751112233', 0.5, 200.00, 'Official Documents', 'DELIVERED', CURRENT_TIMESTAMP - INTERVAL '2 day');
-- Item for Parcel 2 INSERT INTO parcel_item (parcel_id, type, category, weight_in_kg, quantity, fee, created_at) VALUES ((SELECT id FROM parcel WHERE tracking_id = 'SLR-20251009-002'), 'Legal Documents', 'DOCUMENTS', 0.5, 1, 200.00, CURRENT_TIMESTAMP - INTERVAL '2 day');
